package com.projexa.coaching.auth.controller;
import com.projexa.coaching.auth.dto.*; import com.projexa.coaching.auth.service.AuthService; import com.projexa.coaching.common.responses.ApiResponse; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final AuthService auth; public AuthController(AuthService a){auth=a;} @PostMapping("/login") public ApiResponse<LoginResponse> login(@Valid @RequestBody LoginRequest r,HttpServletRequest req){return ApiResponse.of(auth.login(r),req.getAttribute("requestId") instanceof String s?s:null);} @PostMapping("/refresh") public ApiResponse<LoginResponse> refresh(@Valid @RequestBody RefreshRequest r,HttpServletRequest req){return ApiResponse.of(auth.refresh(r.refreshToken()),req.getAttribute("requestId") instanceof String s?s:null);} @PostMapping("/logout") public ResponseEntity<Void> logout(@Valid @RequestBody RefreshRequest r){auth.logout(r.refreshToken());return ResponseEntity.noContent().build();} @GetMapping("/me") public ApiResponse<java.util.Map<String,Object>> me(org.springframework.security.core.Authentication a,HttpServletRequest req){return ApiResponse.of(java.util.Map.of("userId",a.getPrincipal(),"authorities",a.getAuthorities().stream().map(x->x.getAuthority()).toList()),req.getAttribute("requestId") instanceof String s?s:null);}}
